(function () {
const html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Zakat &amp; Tax Planning</title>\n  \n  <!-- Font Awesome Icons -->\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n  <!-- Google Fonts: DM Sans & DM Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:ital,wght@0,300;0,400;0,500;1,300&family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap\" rel=\"stylesheet\">\n\n  <style>\n    /* Embed attached styles.css with overrides where necessary for standalone layout */\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    :root {\n      --bg: #f7f6f2; --surface: #fff; --surface2: #f2f0eb;\n      --border: #e2dfd8; --border-strong: #c8c4bb;\n      --text: #1a1916; --text2: #6b6860; --text3: #a09d98;\n      --green: #1a6b47; --green-bg: #edf7f2;\n      --blue: #1a4a6b; --blue-bg: #edf3f7;\n      --red: #6b1a1a; --red-bg: #f7eded;\n      --gold: #6b4e1a; --gold-bg: #f7f2ed;\n      --orange: #b85c00; --amber: #c97a1a;\n      --r: 6px; --rl: 10px;\n      --shadow: 0 1px 3px rgba(0,0,0,0.06);\n    }\n    body { font-family:'DM Sans',sans-serif; background:var(--bg); color:var(--text); font-size:14px; line-height:1.5; min-height:100vh; }\n\n    /* \u2500\u2500 TOPBAR \u2500\u2500 */\n    .topbar { background:var(--surface); border-bottom:1px solid var(--border); padding:0 1.5rem; display:flex; align-items:center; justify-content:space-between; height:56px; position:sticky; top:0; z-index:200; }\n    .brand { display:flex; align-items:center; gap:10px; }\n    .brand-mark { width:28px; height:28px; background:var(--text); border-radius:6px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }\n    .brand-mark i { color: #fff; font-size: 13px; }\n    .brand-name { font-size:14px; font-weight:500; letter-spacing:-0.01em; }\n    .brand-sub { font-size:12px; color:var(--text3); margin-left:2px; }\n    .pill-nav { display:flex; background:var(--surface2); border-radius:20px; padding:3px; gap:2px; }\n    .pill-btn { padding:5px 16px; border-radius:16px; border:none; background:transparent; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text2); cursor:pointer; font-weight:400; transition:all .15s; }\n    .pill-btn.active { background:var(--surface); color:var(--text); font-weight:500; box-shadow:0 1px 2px rgba(0,0,0,.08); }\n\n    /* \u2500\u2500 PAGE SHELLS \u2500\u2500 */\n    .page { display:none; }\n    .page.active { display:flex; min-height:calc(100vh - 56px); }\n\n    /* \u2500\u2500 ENTRY LAYOUT \u2500\u2500 */\n    .sidebar { width:260px; flex-shrink:0; background:var(--surface); border-right:1px solid var(--border); position:sticky; top:56px; height:calc(100vh - 56px); overflow-y:auto; padding:1.25rem 0; }\n    .main-area { flex:1; padding:2rem; overflow-y:auto; min-width:0; }\n\n    /* sidebar nav */\n    .sb-label { font-size:10px; font-weight:500; letter-spacing:.08em; text-transform:uppercase; color:var(--text3); padding:0 1.25rem; margin-bottom:.5rem; }\n    .sb-item { display:flex; align-items:center; gap:10px; padding:9px 1.25rem; cursor:pointer; border-left:2px solid transparent; transition:all .12s; font-size:13px; color:var(--text2); text-decoration:none; }\n    .sb-item:hover { background:var(--surface2); color:var(--text); }\n    .sb-item.active { border-left-color:var(--text); color:var(--text); font-weight:500; background:var(--surface2); }\n    .sb-dot { width:6px; height:6px; border-radius:50%; flex-shrink:0; }\n    .d1 { background:var(--green); } .d2 { background:var(--blue); } .d3 { background:var(--gold); } .d4 { background:var(--text3); }\n\n    /* progress */\n    .prog-wrap { padding:1.25rem 1.25rem .75rem; }\n    .prog-top { display:flex; justify-content:space-between; font-size:11px; color:var(--text3); margin-bottom:6px; }\n    .prog-track { height:3px; background:var(--surface2); border-radius:2px; overflow:hidden; }\n    .prog-fill { height:100%; background:var(--text); border-radius:2px; width:50%; transition:width .4s; }\n\n    /* per-segment sidebar summaries */\n    .seg-sum { display:none; margin:0 1rem .75rem; }\n    .seg-sum.on { display:block; }\n    .ss-head { background: var(--text); color:#fff; font-size:10px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; padding:6px 10px; border-radius:var(--r) var(--r) 0 0; }\n    .ss-body { background:var(--surface2); border-radius:0 0 var(--r) var(--r); padding:8px 10px; border:1px solid var(--border); border-top:none; }\n    .ss-row { display:flex; justify-content:space-between; align-items:baseline; padding:3px 0; font-size:11px; color:var(--text2); border-bottom:1px solid var(--border); }\n    .ss-row:last-child { border-bottom:none; }\n    .ss-row.neg { color:var(--red); }\n    .ss-v { font-family:'DM Mono',monospace; font-size:11px; color:var(--text); }\n    .ss-b { font-weight:500; }\n    .ss-div { height:1px; background:var(--border-strong); margin:5px 0; }\n    .ss-tot { display:flex; justify-content:space-between; align-items:baseline; padding:3px 0; font-size:11px; font-weight:500; }\n    .positive { color:var(--green); } .negative { color:var(--red); } .neutral { color:var(--blue); } .warning { color:var(--amber); }\n\n    /* \u2500\u2500 SEGMENT CONTENT \u2500\u2500 */\n    .segment { display:none; }\n    .segment.active { display:block; }\n    .seg-hdr { display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:1.75rem; }\n    .seg-tag { display:inline-flex; align-items:center; padding:3px 10px; border-radius:20px; font-size:11px; font-weight:500; margin-bottom:6px; }\n    .t1{background:var(--green-bg);color:var(--green);} .t2{background:var(--blue-bg);color:var(--blue);} .t3{background:var(--gold-bg);color:var(--gold);} .t4{background:var(--surface2);color:var(--text2);}\n    .seg-title { font-size:24px; font-weight:300; letter-spacing:-.03em; }\n    .seg-desc { font-size:13px; color:var(--text3); margin-top:4px; }\n    .seg-tot-box { text-align:right; background:var(--surface2); border-radius:var(--rl); padding:10px 16px; }\n    .tot-label { font-size:11px; color:var(--text3); }\n    .tot-val { font-size:20px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n\n    /* cards */\n    .card { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); margin-bottom:1.5rem; overflow:hidden; box-shadow:var(--shadow); }\n    .ch { display:flex; align-items:center; justify-content:space-between; padding:14px 16px; cursor:pointer; user-select:none; border-bottom:1px solid transparent; transition:background .12s; }\n    .ch:hover { background:var(--surface2); }\n    .ch.open { border-bottom-color:var(--border); }\n    .ch-left { display:flex; align-items:center; gap:10px; }\n    .ci { width:28px; height:28px; border-radius:6px; display:flex; align-items:center; justify-content:center; font-size:13px; flex-shrink:0; }\n    .ci1{background:var(--green-bg); color: var(--green);} \n    .ci2{background:var(--blue-bg); color: var(--blue);} \n    .ci3{background:var(--gold-bg); color: var(--gold);} \n    .ci-r{background:var(--red-bg); color: var(--red);} \n    .ci-g{background:var(--surface2); color: var(--text2);}\n    .ch-title { font-size:13px; font-weight:500; }\n    .ch-sub { font-size:11px; color:var(--text3); margin-top:1px; }\n    .ch-right { display:flex; align-items:center; gap:10px; }\n    .ch-sum { font-family:'DM Mono',monospace; font-size:13px; color:var(--text2); }\n    .chev { width:16px; height:16px; color:var(--text3); transition:transform .2s; flex-shrink:0; }\n    .chev.open { transform:rotate(180deg); }\n    .cb { display:none; padding:14px 16px; }\n    .cb.open { display:block; }\n\n    /* fields */\n    .f-static { display:grid; grid-template-columns:280px 1fr ; gap:12px; align-items:center; padding:10px 0; border-bottom:1px solid var(--border); }\n    .f-static:last-of-type { border-bottom:none; }\n    .f-label { font-size:13px; font-weight: 500; }\n    .f-sub { font-size:11px; color:var(--text3); display: block; font-weight: normal; margin-top: 2px; }\n    \n    .pfx-wrap { position:relative; width: 100%; display: flex; }\n    .pfx { position:absolute; left:10px; top:50%; transform:translateY(-50%); font-size:12px; color:var(--text3); pointer-events:none; }\n    .sfx { position:absolute; right:10px; top:50%; transform:translateY(-50%); font-size:12px; color:var(--text3); pointer-events:none; }\n    .inp { width:100%; height:34px; border:1px solid var(--border); border-radius:var(--r); padding:0 10px; font-size:13px; font-family:'DM Mono',monospace; color:var(--text); background:var(--surface); text-align:right; transition:border-color .12s; }\n    .inp:focus { outline:none; border-color:var(--text); }\n    .inp.pl { padding-left:26px; }\n    .inp.pr { padding-right:54px; }\n    .inp:disabled { background: var(--surface2); color: var(--text3); cursor: not-allowed; }\n\n    /* Custom Switch & Checkbox */\n    .option-row {\n      display: flex;\n      align-items: flex-start;\n      gap: 12px;\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: var(--rl);\n      padding: 1rem;\n      margin-bottom: 1rem;\n      cursor: pointer;\n      transition: all 0.15s ease;\n    }\n    .option-row:hover {\n      border-color: var(--border-strong);\n      box-shadow: var(--shadow);\n    }\n    .option-checkbox-wrapper {\n      position: relative;\n      width: 20px;\n      height: 20px;\n      margin-top: 2px;\n    }\n    .option-checkbox {\n      width: 20px;\n      height: 20px;\n      accent-color: var(--text);\n      cursor: pointer;\n    }\n    .option-label {\n      font-size: 14px;\n      font-weight: 500;\n      color: var(--text);\n    }\n    .option-desc {\n      font-size: 12px;\n      color: var(--text3);\n      margin-top: 2px;\n    }\n\n    /* output assessments */\n    .calc-result-box {\n      border: 1px solid;\n      border-radius: var(--rl);\n      padding: 1.5rem;\n      margin-top: 1.5rem;\n      animation: fi .2s ease;\n    }\n    .res-title {\n      font-size: 11px;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      margin-bottom: 6px;\n    }\n    .res-main-val {\n      font-size: 28px;\n      font-weight: 700;\n      font-family: 'DM Mono', monospace;\n      letter-spacing: -0.04em;\n      margin-bottom: 12px;\n    }\n    .res-grid {\n      display: grid;\n      grid-template-columns: repeat(2, 1fr);\n      gap: 12px;\n      border-top: 1px solid rgba(0,0,0,0.06);\n      padding-top: 12px;\n    }\n    .res-sub-item {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      font-size: 12.5px;\n    }\n    .res-sub-lbl {\n      color: var(--text2);\n    }\n    .res-sub-val {\n      font-family: 'DM Mono', monospace;\n      font-weight: 500;\n    }\n\n    /* Bracket tables style from styles.css */\n    .table-responsive {\n      overflow-x: auto;\n      margin-top: 1rem;\n      border: 1px solid var(--border);\n      border-radius: var(--r);\n    }\n    .bk-table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 12.5px;\n    }\n    .bk-table th {\n      font-size: 11px;\n      font-weight: 500;\n      color: var(--text3);\n      text-align: left;\n      padding: 8px 12px;\n      border-bottom: 1px solid var(--border);\n      background: var(--surface2);\n    }\n    .bk-table td {\n      padding: 8px 12px;\n      border-bottom: 1px solid var(--surface2);\n    }\n    .bk-table td:last-child {\n      text-align: right;\n      font-family: 'DM Mono', monospace;\n    }\n    .bk-table tr.active-tier {\n      background: var(--blue-bg);\n      font-weight: 500;\n    }\n\n    /* commentary */\n    .commentary-block { margin-top: 1.5rem; }\n    .commentary-box { width:100%; min-height:80px; border:1px solid var(--border); border-radius:var(--rl); padding:10px 12px; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text); background:var(--surface); resize:vertical; line-height:1.5; transition:border-color .12s; }\n    .commentary-box:focus { outline:none; border-color:var(--text); }\n    .commentary-box::placeholder { color:var(--text3); }\n    .commentary-lbl { font-size:11px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; color:var(--text3); margin-bottom:6px; display:flex; align-items:center; gap:6px; }\n    .commentary-char { font-size:10px; color:var(--text3); margin-left:auto; font-weight:400; letter-spacing:0; text-transform:none; }\n    .commentary-print { display:none; font-size:12px; color:var(--text2); font-style:italic; margin-top:6px; white-space:pre-wrap; background: var(--surface2); padding: 10px; border-radius: var(--r); border: 1px solid var(--border); }\n\n    /* overall dashboard metric style */\n    .mx-grid { display:grid; grid-template-columns:repeat(3, minmax(0,1fr)); gap:10px; margin-bottom:1.5rem; }\n    .mx-item { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1rem 1.25rem; }\n    .mx-lbl { font-size:11px; color:var(--text3); letter-spacing:.03em; margin-bottom:3px; }\n    .mx-fml { font-size:10px; color:var(--text3); opacity:.7; margin-bottom:8px; font-style:italic; }\n    .mx-val { font-size:22px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n    .mx-sub { font-size:11px; color:var(--text3); margin-top:3px; }\n\n    /* buttons */\n    .btn-pdf { display:inline-flex; align-items:center; gap:7px; padding:8px 18px; background:var(--text); color:#fff; border:none; border-radius:var(--r); font-size:13px; font-family:'DM Sans',sans-serif; font-weight:500; cursor:pointer; transition:opacity .15s; white-space:nowrap; flex-shrink:0; }\n    .btn-pdf:hover { opacity:.85; }\n    .btn-reset-data { display:inline-flex; align-items:center; gap:4px; padding:4px 9px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:11px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; transition:all .12s; margin-left:6px; }\n    .btn-reset-data:hover { border-color:#c0392b; color:#c0392b; background:#fff5f5; }\n\n    .action-btn { display: inline-flex; align-items: center; gap: 8px; padding: 8px 16px; background: var(--text); color: #fff; border: none; border-radius: var(--r); font-size: 12.5px; font-weight: 500; cursor: pointer; transition: background 0.15s; }\n    .action-btn:hover { background: #333; }\n\n    /* helper info bar */\n    .info-bar { display: flex; align-items: flex-start; gap: 10px; padding: 10px 14px; border-radius: var(--r); font-size: 12.5px; margin-bottom: 1.25rem; line-height: 1.45; }\n    .info-bar i { font-size: 14px; margin-top: 2px; }\n\n    /* layout adjustments */\n    @media(max-width:768px){\n      .sidebar{display:none;}\n      .mx-grid{grid-template-columns:1fr;}\n      .f-static{grid-template-columns:1fr; gap:6px;}\n      .inp.pl{width: 100%;}\n    }\n\n    /* Print styles matching styles.css */\n    @media print {\n      * { -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; }\n      body { background:#f7f6f2 !important; margin:0; }\n      .topbar, .sidebar, .btn-pdf, .btn-reset-data, .commentary-box, .commentary-lbl, .commentary-char, .pill-nav { display:none !important; }\n      .page { display:block !important; min-height:auto !important; }\n      .main-area { padding:12px !important; max-width:100% !important; }\n      .commentary-print { display:block !important; }\n      .card { break-inside:avoid; page-break-inside:avoid; margin-bottom:10px !important; padding:12px !important; border:1px solid #e2dfd8 !important; border-radius:8px !important; }\n      .calc-result-box { break-inside:avoid; page-break-inside:avoid; }\n      .bk-table { font-size: 11px; }\n    }\n  </style>\n\n<style id=\"planning-suite-frame-overrides\">\n  html, body { min-height: 100%; }\n  body { margin: 0 !important; padding: 0 !important; background: #f7f6f2 !important; }\n  .topbar, .sidebar { display: none !important; }\n  .page.active { min-height: 100vh !important; display: block !important; }\n  .main-area { width: 100% !important; max-width: 1240px !important; margin: 0 auto !important; padding: 2rem !important; box-sizing: border-box !important; }\n  .container { max-width: 1240px !important; padding: 2rem !important; }\n  @media (max-width: 900px) { .main-area, .container { padding: 1rem !important; } .f-static { grid-template-columns: 1fr !important; } }\n</style>\n</head>\n<body>\n\n  <!-- TOPBAR -->\n  <div class=\"topbar\">\n    <div class=\"brand\">\n      <div class=\"brand-mark\">\n        <i class=\"fa-solid fa-coins\"></i>\n      </div>\n      <div>\n        <span class=\"brand-name\">Zakat & Tax Planner</span>\n        <span class=\"brand-sub\">YA 2025 / 2026 Desktop</span>\n      </div>\n    </div>\n    <div style=\"display: flex; align-items: center; gap: 8px;\">\n      <button class=\"btn-pdf\" onclick=\"window.print()\">\n        <i class=\"fa-solid fa-print\"></i> Print Report\n      </button>\n      <button class=\"btn-reset-data\" onclick=\"resetAll()\">\n        <i class=\"fa-solid fa-rotate-left\"></i> Reset Desk\n      </button>\n    </div>\n  </div>\n\n  <!-- MAIN WRAPPER -->\n  <div class=\"page active\">\n    \n    <!-- SIDEBAR -->\n    <div class=\"sidebar\">\n      <div class=\"prog-wrap\">\n        <div class=\"prog-top\">\n          <span>Desk Planning Setup</span>\n          <span id=\"completion-lbl\">50% Completed</span>\n        </div>\n        <div class=\"prog-track\">\n          <div class=\"prog-fill\" id=\"completion-bar\"></div>\n        </div>\n      </div>\n\n      <div class=\"sb-label\">Assessments</div>\n      <a href=\"#overview-panel\" class=\"sb-item active\" onclick=\"scrollToElement('overview-panel', this)\">\n        <span class=\"sb-dot d1\"></span> Consolidated View\n      </a>\n      <a href=\"#tax-panel\" class=\"sb-item\" id=\"sb-nav-tax\" onclick=\"scrollToElement('tax-panel-header', this)\">\n        <span class=\"sb-dot d2\"></span> YA 2025 Tax Calculator\n      </a>\n      <a href=\"#zakat-panel\" class=\"sb-item\" id=\"sb-nav-zakat\" onclick=\"scrollToElement('zakat-panel-header', this)\">\n        <span class=\"sb-dot d3\"></span> Selangor Zakat Planner\n      </a>\n\n      <!-- Quick Summary inside Sidebar matching styles.css pattern -->\n      <div class=\"sb-label\" style=\"margin-top:1.5rem;\">Live Summary</div>\n      <div class=\"seg-sum on\" style=\"display: block;\">\n        <div class=\"ss-head\">Quick Summary</div>\n        <div class=\"ss-body\">\n          <div class=\"ss-row\">\n            <span>Chargeable Income:</span>\n            <span class=\"ss-v\" id=\"sb-chargeable\">RM 0.00</span>\n          </div>\n          <div class=\"ss-row\">\n            <span>Est. Income Tax:</span>\n            <span class=\"ss-v text-blue\" id=\"sb-tax-due\" style=\"color:var(--blue)\">RM 0.00</span>\n          </div>\n          <div class=\"ss-row\">\n            <span>Assessable Zakat:</span>\n            <span class=\"ss-v\" id=\"sb-zakat-wealth\">RM 0.00</span>\n          </div>\n          <div class=\"ss-row\">\n            <span>Est. Zakat Due:</span>\n            <span class=\"ss-v\" id=\"sb-zakat-due\" style=\"color:var(--gold)\">RM 0.00</span>\n          </div>\n          <div class=\"ss-div\"></div>\n          <div class=\"ss-tot\">\n            <span>Combined Outflow:</span>\n            <span class=\"ss-v ss-b positive\" id=\"sb-total-outflow\" style=\"color:var(--green)\">RM 0.00</span>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- MAIN AREA -->\n    <div class=\"main-area\">\n      \n      <!-- HEADER -->\n      <div class=\"a-header\">\n        <div class=\"a-header-left\">\n          <h1 class=\"a-title\">Zakat & Tax Planning Desk</h1>\n          <p class=\"a-sub\">Integrate your LHDN Malaysian progressive taxes with regional wealth zakat allocations systematically.</p>\n        </div>\n      </div>\n\n      <!-- OBJECTIVE & CONFIGURATION CARD -->\n      <div class=\"card\" id=\"overview-panel\">\n        <div class=\"ch open\">\n          <div class=\"ch-left\">\n            <div class=\"ci ci1\"><i class=\"fa-solid fa-crosshairs\"></i></div>\n            <div>\n              <span class=\"ch-title\">Desk Configuration & Directives</span>\n              <p class=\"ch-sub\">Configure active planning modules for the current assessment period</p>\n            </div>\n          </div>\n        </div>\n        <div class=\"cb open\">\n          <div class=\"info-bar\" style=\"background: var(--surface2); color: var(--text);\">\n            <i class=\"fa-solid fa-calculator\"></i>\n            <span><strong>Objective:</strong> Stay tax-compliant while optimizing your personal tax reliefs, and track zakat obligations across cash savings, mutual stock portfolios, and precious physical gold assets.</span>\n          </div>\n\n          <div style=\"display: flex; flex-direction: column; gap: 10px; margin-top: 10px;\">\n            <!-- Checkbox 1: Tax Planning -->\n            <div class=\"option-row\" onclick=\"togglePlannerCheckbox('tax')\">\n              <div class=\"option-checkbox-wrapper\">\n                <input type=\"checkbox\" id=\"chk-tax\" class=\"option-checkbox\" checked onclick=\"event.stopPropagation(); handleCheckboxChange()\">\n              </div>\n              <div>\n                <div class=\"option-label\">I want to plan my Payable Tax for YA 2025</div>\n                <div class=\"option-desc\">Loads the latest LHDN progressive bracket rules and deductions to evaluate monthly tax prepaid offset (MTD/PCB).</div>\n              </div>\n            </div>\n\n            <!-- Checkbox 2: Zakat Planning -->\n            <div class=\"option-row\" onclick=\"togglePlannerCheckbox('zakat')\">\n              <div class=\"option-checkbox-wrapper\">\n                <input type=\"checkbox\" id=\"chk-zakat\" class=\"option-checkbox\" checked onclick=\"event.stopPropagation(); handleCheckboxChange()\">\n              </div>\n              <div>\n                <div class=\"option-label\">I want to plan my Payable Zakat for Year 2026</div>\n                <div class=\"option-desc\">Evaluates savings, investments, stored gold (85g threshold), and worn gold (800g Selangor Uruf) using current Nisab.</div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- OVERALL MATRIX SUMMARY PANEL -->\n      <div class=\"card\" id=\"combined-summary-card\">\n        <div class=\"ch open\">\n          <div class=\"ch-left\">\n            <div class=\"ci ci3\"><i class=\"fa-solid fa-chart-pie\"></i></div>\n            <div>\n              <span class=\"ch-title\">Consolidated Wealth Outflow Assessment</span>\n              <p class=\"ch-sub\">Global planning figures for the active desk session</p>\n            </div>\n          </div>\n        </div>\n        <div class=\"cb open\">\n          <div class=\"mx-grid\">\n            <!-- Tax KPI Card -->\n            <div class=\"mx-item\" style=\"border-left: 3.5px solid var(--blue)\">\n              <div class=\"mx-lbl\">Income Tax Due</div>\n              <div class=\"mx-fml\">LHDN Progressive Band</div>\n              <div class=\"mx-val text-blue\" id=\"lbl-tax-payable\" style=\"color: var(--blue);\">RM 0.00</div>\n              <div class=\"mx-sub\" id=\"lbl-tax-sub\">Based on YA 2025</div>\n            </div>\n\n            <!-- Zakat KPI Card -->\n            <div class=\"mx-item\" style=\"border-left: 3.5px solid var(--gold)\">\n              <div class=\"mx-lbl\">Zakat Obligation</div>\n              <div class=\"mx-fml\">2.5% on Wealth Assets</div>\n              <div class=\"mx-val\" id=\"lbl-zakat-payable\" style=\"color: var(--gold);\">RM 0.00</div>\n              <div class=\"mx-sub\" id=\"lbl-zakat-sub\">Nisab Threshold: RM 24,500</div>\n            </div>\n\n            <!-- Combined KPI Card -->\n            <div class=\"mx-item\" style=\"border-left: 3.5px solid var(--green)\">\n              <div class=\"mx-lbl\">Combined Outflow</div>\n              <div class=\"mx-fml\">Tax + Zakat Obligations</div>\n              <div class=\"mx-val\" id=\"lbl-combined-outflow\" style=\"color: var(--green);\">RM 0.00</div>\n              <div class=\"mx-sub\" id=\"lbl-combined-sub\">Dynamic Zakat rebate applied to Tax</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- INCOME TAX CALCULATOR PANEL -->\n      <div class=\"card\" id=\"tax-panel\" style=\"display: block;\">\n        <div class=\"ch open\" id=\"tax-panel-header\" onclick=\"toggleCardCollapse('tax-card-body', 'tax-chev')\">\n          <div class=\"ch-left\">\n            <div class=\"ci ci2\"><i class=\"fa-solid fa-file-invoice-dollar\"></i></div>\n            <div>\n              <span class=\"ch-title\">Payable Tax Calculator (YA 2025 Model)</span>\n              <span class=\"ch-sub\">Resident Individual Progressive Bracket Structure</span>\n            </div>\n          </div>\n          <div class=\"ch-right\">\n            <span class=\"ch-sum\" id=\"header-tax-sum\">RM 0.00</span>\n            <i class=\"fa-solid fa-chevron-up chev open\" id=\"tax-chev\"></i>\n          </div>\n        </div>\n        \n        <div class=\"cb open\" id=\"tax-card-body\">\n          <div class=\"info-bar\" style=\"background: var(--blue-bg); color: var(--blue);\">\n            <i class=\"fa-solid fa-circle-info\"></i>\n            <span>Calculations follow LHDN progressive brackets for YA 2025. Registered reliefs are deducted directly from gross income to reduce overall Chargeable Income.</span>\n          </div>\n\n          <!-- Basic Gross Income Input -->\n          <div class=\"f-static\">\n            <div>\n              <span class=\"f-label\">Annual Gross Income</span>\n              <span class=\"f-sub\">Base salary, bonuses, commissions, and other taxable income.</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-gross-income\" class=\"inp pl\" value=\"78000\" oninput=\"runCalculations()\">\n            </div>\n          </div>\n\n          <!-- Tax Relief Sub-Registry Header -->\n          <div style=\"margin-top: 1.25rem; margin-bottom: 0.5rem; border-bottom: 1px solid var(--border); padding-bottom: 4px;\">\n            <span class=\"f-label\" style=\"font-weight: 700; color: var(--text2);\">Claimable Tax Relief Sub-Registry</span>\n          </div>\n\n          <!-- Individual Relief -->\n          <div class=\"f-static\">\n            <div>\n              <span class=\"f-label\">Individual & Dependent Relief</span>\n              <span class=\"f-sub\">Automatic baseline statutory relief.</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-relief-individual\" class=\"inp pl\" value=\"9000\" disabled>\n            </div>\n          </div>\n\n          <!-- Medical Expense Relief -->\n          <div class=\"f-static\">\n            <div>\n              <span class=\"f-label\">Medical Expense Relief (Self/Spouse/Parent)</span>\n              <span class=\"f-sub\">Serious illness therapies, parents' treatment, vaccinations (Cap: RM 10,000).</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-relief-medical\" class=\"inp pl\" value=\"1500\" max=\"10000\" oninput=\"runCalculations()\">\n            </div>\n          </div>\n\n          <!-- Lifestyle Relief -->\n          <div class=\"f-static\">\n            <div>\n              <span class=\"f-label\">Lifestyle Relief (Books/Internet/Tech/Sports)</span>\n              <span class=\"f-sub\">Purchase of books, devices, sports gear, and subscription bills (Cap: RM 2,500).</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-relief-lifestyle\" class=\"inp pl\" value=\"2000\" max=\"2500\" oninput=\"runCalculations()\">\n            </div>\n          </div>\n\n          <!-- EPF Contributions -->\n          <div class=\"f-static\">\n            <div>\n              <span class=\"f-label\">EPF Contributions</span>\n              <span class=\"f-sub\">Mandatory or voluntary Employees Provident Fund deposits (Cap: RM 4,000).</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-relief-epf\" class=\"inp pl\" value=\"4000\" max=\"4000\" oninput=\"runCalculations()\">\n            </div>\n          </div>\n\n          <!-- Life Insurance Premiums -->\n          <div class=\"f-static\">\n            <div>\n              <span class=\"f-label\">Life Insurance Premiums</span>\n              <span class=\"f-sub\">Premiums paid on personal or spouse policies (Cap: RM 3,000).</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-relief-life-ins\" class=\"inp pl\" value=\"3000\" max=\"3000\" oninput=\"runCalculations()\">\n            </div>\n          </div>\n\n          <!-- SSPN Savings -->\n          <div class=\"f-static\">\n            <div>\n              <span class=\"f-label\">SSPN Savings Net Deposit</span>\n              <span class=\"f-sub\">Net deposits made to National Education Savings Scheme (Cap: RM 8,000).</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-relief-sspn\" class=\"inp pl\" value=\"0\" max=\"8000\" oninput=\"runCalculations()\">\n            </div>\n          </div>\n\n          <!-- MTD Paid -->\n          <div class=\"f-static\" style=\"margin-top: 1.25rem;\">\n            <div>\n              <span class=\"f-label\">Monthly Tax Deduction (MTD / PCB) Paid</span>\n              <span class=\"f-sub\">Prepaid monthly taxes deducted automatically by your employer.</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-mtd-paid\" class=\"inp pl\" value=\"1800\" oninput=\"runCalculations()\">\n            </div>\n          </div>\n\n          <!-- Zakat Offset Input -->\n          <div class=\"f-static\">\n            <div>\n              <span class=\"f-label\">Annual Zakat Payments (Rebated directly)</span>\n              <span class=\"f-sub\">Islamic religious dues act as a 100% direct rebate off total computed tax.</span>\n            </div>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" id=\"tax-zakat-paid\" class=\"inp pl\" value=\"0\" oninput=\"runCalculations()\">\n            </div>\n          </div>\n\n          <!-- Runs Calculation Button -->\n          <div style=\"text-align: right; margin-top: 12px;\">\n            <button class=\"action-btn\" onclick=\"runCalculations()\"><i class=\"fa-solid fa-calculator\"></i> Run Tax Calculation</button>\n          </div>\n\n          <!-- Tax Output Assessment Box -->\n          <div class=\"calc-result-box\" style=\"background: var(--blue-bg); border-color: rgba(26, 74, 107, 0.15)\">\n            <div class=\"res-title\" style=\"color: var(--blue);\">Tax Liability Assessment (YA 2025)</div>\n            <div class=\"res-main-val\" id=\"tax-final-liability-val\" style=\"color: var(--blue);\">RM 0.00</div>\n            \n            <div class=\"res-grid\">\n              <div class=\"res-sub-item\">\n                <span class=\"res-sub-lbl\">Chargeable Income:</span>\n                <span class=\"res-sub-val\" id=\"res-tax-chargeable\">RM 0.00</span>\n              </div>\n              <div class=\"res-sub-item\">\n                <span class=\"res-sub-lbl\">Total Claimed Reliefs:</span>\n                <span class=\"res-sub-val\" id=\"res-tax-reliefs\">RM 0.00</span>\n              </div>\n              <div class=\"res-sub-item\">\n                <span class=\"res-sub-lbl\">Calculated Tax (Pre-rebates):</span>\n                <span class=\"res-sub-val\" id=\"res-tax-calculated-owed\">RM 0.00</span>\n              </div>\n              <div class=\"res-sub-item\">\n                <span class=\"res-sub-lbl\">Eligible Rebates Applied:</span>\n                <span class=\"res-sub-val\" id=\"res-tax-rebates\">RM 0.00</span>\n              </div>\n            </div>\n\n            <div style=\"margin-top: 1rem; font-size: 13px; font-weight: 700;\">\n              Filing Action State: <span id=\"res-tax-status-text\" class=\"neutral\">Balanced</span>\n            </div>\n\n            <!-- Tax Progressive Breakdown Table -->\n            <div class=\"table-responsive\">\n              <table class=\"bk-table\">\n                <thead>\n                  <tr>\n                    <th>Chargeable Tier (RM)</th>\n                    <th>Rate (%)</th>\n                    <th style=\"text-align: right;\">Calculated Tax within Tier (RM)</th>\n                  </tr>\n                </thead>\n                <tbody id=\"bracket-table-body\">\n                  <!-- Generated by JS -->\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Commentary Block for Tax -->\n          <div class=\"commentary-block\">\n            <div class=\"commentary-lbl\">\n              <span>YA 2025 Tax Notes / Reminders</span>\n              <span class=\"commentary-char\" id=\"char-count-tax\">0 / 250 chars</span>\n            </div>\n            <textarea id=\"commentary-tax\" class=\"commentary-box\" placeholder=\"e.g. Remember to gather receipts for lifestyle purchases and life insurance statements before LHDN deadline...\" maxlength=\"250\" oninput=\"updateCommentary('tax')\"></textarea>\n            <div class=\"commentary-print\" id=\"print-tax-commentary\">No notes specified.</div>\n          </div>\n        </div>\n      </div>\n\n      <!-- ZAKAT WEALTH CALCULATOR PANEL -->\n      <div class=\"card\" id=\"zakat-panel\" style=\"display: block;\">\n        <div class=\"ch open\" id=\"zakat-panel-header\" onclick=\"toggleCardCollapse('zakat-card-body', 'zakat-chev')\">\n          <div class=\"ch-left\">\n            <div class=\"ci ci3\"><i class=\"fa-solid fa-coins\"></i></div>\n            <div>\n              <span class=\"ch-title\">Payable Zakat Planner (Selangor Model)</span>\n              <span class=\"ch-sub\">Savings, Portfolio, and Precious Metals Wealth Zakat</span>\n            </div>\n          </div>\n          <div class=\"ch-right\">\n            <span class=\"ch-sum\" id=\"header-zakat-sum\">RM 0.00</span>\n            <i class=\"fa-solid fa-chevron-up chev open\" id=\"zakat-chev\"></i>\n          </div>\n        </div>\n\n        <div class=\"cb open\" id=\"zakat-card-body\">\n          <div class=\"info-bar\" style=\"background: var(--gold-bg); color: var(--gold);\">\n            <i class=\"fa-solid fa-triangle-exclamation\"></i>\n            <span>Zakat is applicable at exactly 2.5% on wealth holdings once total assessable liquid holdings exceed the annual Nisab threshold. Current Selangor Nisab: <strong>RM 24,500.00</strong>.</span>\n          </div>\n\n          <!-- Cash & Savings -->\n          <div style=\"background: var(--surface2); padding: 12px; border-radius: var(--r); margin-bottom: 12px; border: 1px solid var(--border);\">\n            <span class=\"f-label\" style=\"font-weight: 700; color: var(--gold)\">1. Zakat on Cash & Savings Accounts</span>\n            <p class=\"f-sub\" style=\"margin-bottom: 8px;\">Assessable value computed from the lowest combined aggregate balance of your cash deposits across the year.</p>\n            <div class=\"f-static\" style=\"border-bottom:none; padding: 4px 0;\">\n              <div><span class=\"f-label\">Lowest Consolidated Annual Balance</span></div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">RM</span>\n                <input type=\"number\" id=\"zakat-savings-bal\" class=\"inp pl\" value=\"18000\" oninput=\"runCalculations()\">\n              </div>\n            </div>\n          </div>\n\n          <!-- Shares & Portfolios -->\n          <div style=\"background: var(--surface2); padding: 12px; border-radius: var(--r); margin-bottom: 12px; border: 1px solid var(--border);\">\n            <span class=\"f-label\" style=\"font-weight: 700; color: var(--gold)\">2. Zakat on Shares & Mutual Portfolios</span>\n            <p class=\"f-sub\" style=\"margin-bottom: 8px;\">Assessable value of stocks, unit trust funds, and active digital portfolios at year-end market valuation.</p>\n            <div class=\"f-static\" style=\"border-bottom:none; padding: 4px 0;\">\n              <div><span class=\"f-label\">Market Value of Stock Holdings</span></div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">RM</span>\n                <input type=\"number\" id=\"zakat-stocks-bal\" class=\"inp pl\" value=\"25000\" oninput=\"runCalculations()\">\n              </div>\n            </div>\n          </div>\n\n          <!-- Precious Gold Holdings -->\n          <div style=\"background: var(--surface2); padding: 12px; border-radius: var(--r); margin-bottom: 12px; border: 1px solid var(--border);\">\n            <span class=\"f-label\" style=\"font-weight: 700; color: var(--gold)\">3. Zakat on Physical / Account Gold Holdings</span>\n            <p class=\"f-sub\" style=\"margin-bottom: 8px;\">Nisab limit for stored/investment gold bar is 85g. Customary worn gold jewelry in Selangor has an Uruf exemption up to 800g.</p>\n            \n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Weight of Investment Gold (Stored)</span>\n                <span class=\"f-sub\">Gold bars, bullion, digital gold accounts, or un-worn stored ornaments.</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <input type=\"number\" id=\"zakat-gold-stored\" class=\"inp pr\" value=\"90\" oninput=\"runCalculations()\">\n                <span class=\"sfx\">Grams</span>\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Weight of Worn Gold Ornaments</span>\n                <span class=\"f-sub\">Customary worn jewelry. Selangor Uruf threshold is 800g (Excess weight is zakatable).</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <input type=\"number\" id=\"zakat-gold-worn\" class=\"inp pr\" value=\"15\" oninput=\"runCalculations()\">\n                <span class=\"sfx\">Grams</span>\n              </div>\n            </div>\n\n            <div class=\"f-static\" style=\"border-bottom:none;\">\n              <div>\n                <span class=\"f-label\">Current Market Price of Gold</span>\n                <span class=\"f-sub\">Valuation rate of gold per-gram for the assessment date.</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <input type=\"number\" id=\"zakat-gold-price\" class=\"inp pr\" value=\"340\" oninput=\"runCalculations()\">\n                <span class=\"sfx\">RM/g</span>\n              </div>\n            </div>\n          </div>\n\n          <!-- Runs Calculation Button -->\n          <div style=\"text-align: right; margin-top: 12px;\">\n            <button class=\"action-btn\" onclick=\"runCalculations()\"><i class=\"fa-solid fa-coins\"></i> Calculate Zakat</button>\n          </div>\n\n          <!-- Zakat Output Assessment Box -->\n          <div class=\"calc-result-box\" style=\"background: var(--gold-bg); border-color: rgba(107, 78, 26, 0.15)\">\n            <div class=\"res-title\" style=\"color: var(--gold);\">Estimated Zakat Obligation Summary</div>\n            <div class=\"res-main-val\" id=\"zakat-final-val\" style=\"color: var(--gold);\">RM 0.00</div>\n            \n            <div class=\"res-grid\">\n              <div class=\"res-sub-item\">\n                <span class=\"res-sub-lbl\">Total Zakat-Assessable Wealth:</span>\n                <span class=\"res-sub-val\" id=\"res-zakat-wealth\">RM 0.00</span>\n              </div>\n              <div class=\"res-sub-item\">\n                <span class=\"res-sub-lbl\">Nisab Limit Check (RM 24,500.00):</span>\n                <span class=\"res-sub-val\" id=\"res-zakat-nisab-check\">Passed</span>\n              </div>\n              <div class=\"res-sub-item\">\n                <span class=\"res-sub-lbl\">Assessable Stored Gold Value:</span>\n                <span class=\"res-sub-val\" id=\"res-gold-stored-val\">RM 0.00</span>\n              </div>\n              <div class=\"res-sub-item\">\n                <span class=\"res-sub-lbl\">Assessable Worn Gold Value (Excess):</span>\n                <span class=\"res-sub-val\" id=\"res-gold-worn-val\">RM 0.00</span>\n              </div>\n            </div>\n          </div>\n\n          <!-- Commentary Block for Zakat -->\n          <div class=\"commentary-block\">\n            <div class=\"commentary-lbl\">\n              <span>Zakat Planning & Payment Notes</span>\n              <span class=\"commentary-char\" id=\"char-count-zakat\">0 / 250 chars</span>\n            </div>\n            <textarea id=\"commentary-zakat\" class=\"commentary-box\" placeholder=\"e.g. Schedule payment to Selangor Zakat Board. Note down the transaction receipt to claim direct rebate on tax...\" maxlength=\"250\" oninput=\"updateCommentary('zakat')\"></textarea>\n            <div class=\"commentary-print\" id=\"print-zakat-commentary\">No notes specified.</div>\n          </div>\n        </div>\n      </div>\n\n    </div>\n  </div>\n\n  <script>\n    // System Configurations\n    const NISAB_THRESHOLD = 24500.00;\n\n    // LHDN YA 2025 Progressive Brackets Reference\n    const TAX_BRACKETS_YA_2025 = [\n      { min: 0, max: 5000, rate: 0.00, taxBase: 0 },\n      { min: 5000, max: 20000, rate: 0.01, taxBase: 0 },\n      { min: 20000, max: 35000, rate: 0.03, taxBase: 150 },\n      { min: 35000, max: 50000, rate: 0.06, taxBase: 600 },\n      { min: 50000, max: 70000, rate: 0.11, taxBase: 1500 },\n      { min: 70000, max: 100000, rate: 0.19, taxBase: 3700 },\n      { min: 100000, max: 400000, rate: 0.25, taxBase: 9400 },\n      { min: 400000, max: 600000, rate: 0.26, taxBase: 84400 },\n      { min: 600000, max: 2000000, rate: 0.28, taxBase: 136400 },\n      { min: 2000000, max: Infinity, rate: 0.30, taxBase: 528400 }\n    ];\n\n    window.onload = function() {\n      // Default state initializes both planners\n      runCalculations();\n      updateProgress();\n    };\n\n    // Scroll smoothly to target element\n    function scrollToElement(id, element) {\n      // Manage active state classes in sidebar\n      const items = document.querySelectorAll('.sb-item');\n      items.forEach(item => item.classList.remove('active'));\n      element.classList.add('active');\n\n      const target = document.getElementById(id);\n      if (target) {\n        target.scrollIntoView({ behavior: 'smooth', block: 'start' });\n      }\n    }\n\n    // Interactive Card Collapse/Expand toggler\n    function toggleCardCollapse(bodyId, chevId) {\n      const body = document.getElementById(bodyId);\n      const chev = document.getElementById(chevId);\n      if (body.classList.contains('open')) {\n        body.classList.remove('open');\n        chev.classList.remove('open');\n      } else {\n        body.classList.add('open');\n        chev.classList.add('open');\n      }\n    }\n\n    // Toggle planner panel display via the option card click\n    function togglePlannerCheckbox(type) {\n      const chk = document.getElementById('chk-' + type);\n      chk.checked = !chk.checked;\n      handleCheckboxChange();\n    }\n\n    // Processes checkbox changes to display correct cards and recalculate\n    function handleCheckboxChange() {\n      const isTaxPlanned = document.getElementById('chk-tax').checked;\n      const isZakatPlanned = document.getElementById('chk-zakat').checked;\n\n      const taxPanel = document.getElementById('tax-panel');\n      const zakatPanel = document.getElementById('zakat-panel');\n      const sbTax = document.getElementById('sb-nav-tax');\n      const sbZakat = document.getElementById('sb-nav-zakat');\n\n      // Update Panel visibility\n      taxPanel.style.display = isTaxPlanned ? 'block' : 'none';\n      sbTax.style.display = isTaxPlanned ? 'flex' : 'none';\n\n      zakatPanel.style.display = isZakatPlanned ? 'block' : 'none';\n      sbZakat.style.display = isZakatPlanned ? 'flex' : 'none';\n\n      runCalculations();\n      updateProgress();\n    }\n\n    // Dynamic UI Progress bar update\n    function updateProgress() {\n      const isTaxPlanned = document.getElementById('chk-tax').checked;\n      const isZakatPlanned = document.getElementById('chk-zakat').checked;\n      const fill = document.getElementById('completion-fill');\n      const bar = document.getElementById('completion-bar');\n      const lbl = document.getElementById('completion-lbl');\n\n      let score = 0;\n      if (isTaxPlanned) score += 50;\n      if (isZakatPlanned) score += 50;\n\n      bar.style.width = score + '%';\n      lbl.innerText = score + '% Completed';\n    }\n\n    // Core dynamic calculation runner\n    function runCalculations() {\n      let finalTaxCalculated = 0.00;\n      let finalZakatCalculated = 0.00;\n\n      const isTaxPlanned = document.getElementById('chk-tax').checked;\n      const isZakatPlanned = document.getElementById('chk-zakat').checked;\n\n      // 1. Determine Zakat (Calculate Zakat first so its rebate can automatically feed into Tax Relieves)\n      if (isZakatPlanned) {\n        finalZakatCalculated = calculateZakat();\n      } else {\n        document.getElementById('header-zakat-sum').innerText = 'RM 0.00';\n        document.getElementById('lbl-zakat-payable').innerText = 'RM 0.00';\n        document.getElementById('sb-zakat-wealth').innerText = 'RM 0.00';\n        document.getElementById('sb-zakat-due').innerText = 'RM 0.00';\n      }\n\n      // Auto-populate the Tax Zakat payment with calculated Zakat if both active\n      if (isTaxPlanned && isZakatPlanned) {\n        document.getElementById('tax-zakat-paid').value = Math.round(finalZakatCalculated);\n      }\n\n      // 2. Determine Income Tax\n      if (isTaxPlanned) {\n        finalTaxCalculated = calculateTax();\n      } else {\n        document.getElementById('header-tax-sum').innerText = 'RM 0.00';\n        document.getElementById('lbl-tax-payable').innerText = 'RM 0.00';\n        document.getElementById('sb-chargeable').innerText = 'RM 0.00';\n        document.getElementById('sb-tax-due').innerText = 'RM 0.00';\n      }\n\n      // Update Combined KPIS\n      const totalCombined = finalTaxCalculated + finalZakatCalculated;\n      document.getElementById('lbl-combined-outflow').innerText = 'RM ' + totalCombined.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('sb-total-outflow').innerText = 'RM ' + totalCombined.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n    }\n\n    // Specific Tax formula algorithm (replicates official YA 2025 progressive system)\n    function calculateTax() {\n      const grossIncome = parseFloat(document.getElementById('tax-gross-income').value) || 0;\n\n      // Collect relieves\n      const individualRelief = 9000;\n      const medicalRelief = Math.min(parseFloat(document.getElementById('tax-relief-medical').value) || 0, 10000);\n      const lifestyleRelief = Math.min(parseFloat(document.getElementById('tax-relief-lifestyle').value) || 0, 2500);\n      const epfRelief = Math.min(parseFloat(document.getElementById('tax-relief-epf').value) || 0, 4000);\n      const lifeInsRelief = Math.min(parseFloat(document.getElementById('tax-relief-life-ins').value) || 0, 3000);\n      const sspnRelief = Math.min(parseFloat(document.getElementById('tax-relief-sspn').value) || 0, 8000);\n\n      // Force Caps back into UI inputs visually if user exceeded\n      document.getElementById('tax-relief-medical').value = medicalRelief;\n      document.getElementById('tax-relief-lifestyle').value = lifestyleRelief;\n      document.getElementById('tax-relief-epf').value = epfRelief;\n      document.getElementById('tax-relief-life-ins').value = lifeInsRelief;\n      document.getElementById('tax-relief-sspn').value = sspnRelief;\n\n      const totalReliefs = individualRelief + medicalRelief + lifestyleRelief + epfRelief + lifeInsRelief + sspnRelief;\n      \n      let chargeableIncome = grossIncome - totalReliefs;\n      if (chargeableIncome < 0) chargeableIncome = 0;\n\n      // Calculate progressive bracket\n      let computedTax = 0;\n      let remainingChargeable = chargeableIncome;\n      let bracketHTML = '';\n\n      for (let i = 0; i < TAX_BRACKETS_YA_2025.length; i++) {\n        const bracket = TAX_BRACKETS_YA_2025[i];\n        const nextBracketMin = (i + 1 < TAX_BRACKETS_YA_2025.length) ? TAX_BRACKETS_YA_2025[i + 1].min : Infinity;\n        const tierBandwidth = nextBracketMin - bracket.min;\n\n        let taxableInThisTier = 0;\n        let isCurrentActiveTier = false;\n\n        if (remainingChargeable > 0) {\n          if (remainingChargeable > tierBandwidth) {\n            taxableInThisTier = tierBandwidth;\n            remainingChargeable -= tierBandwidth;\n          } else {\n            taxableInThisTier = remainingChargeable;\n            remainingChargeable = 0;\n            isCurrentActiveTier = true;\n          }\n\n          const taxInThisTier = taxableInThisTier * bracket.rate;\n          computedTax += taxInThisTier;\n\n          const activeRangeLabel = bracket.max === Infinity ? `Above ${bracket.min.toLocaleString()}` : `${bracket.min.toLocaleString()} - ${bracket.max.toLocaleString()}`;\n          bracketHTML += `\n            <tr class=\"${isCurrentActiveTier ? 'active-tier' : ''}\">\n              <td>${activeRangeLabel}</td>\n              <td>${(bracket.rate * 100).toFixed(0)}%</td>\n              <td>RM ${taxInThisTier.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>\n            </tr>\n          `;\n        } else {\n          // Inactive ranges\n          const inactiveRangeLabel = bracket.max === Infinity ? `Above ${bracket.min.toLocaleString()}` : `${bracket.min.toLocaleString()} - ${bracket.max.toLocaleString()}`;\n          bracketHTML += `\n            <tr>\n              <td>${inactiveRangeLabel}</td>\n              <td>${(bracket.rate * 100).toFixed(0)}%</td>\n              <td style=\"color: var(--text3)\">RM 0.00</td>\n            </tr>\n          `;\n        }\n      }\n\n      document.getElementById('bracket-table-body').innerHTML = bracketHTML;\n\n      // Apply rebates\n      let rebatesApplied = 0;\n\n      // Baseline low chargeable income rebate (< RM35k)\n      if (chargeableIncome <= 35000 && chargeableIncome > 0) {\n        rebatesApplied += 400;\n      }\n\n      // Zakat rebate (directly deducts tax)\n      const zakatPaidInput = parseFloat(document.getElementById('tax-zakat-paid').value) || 0;\n      rebatesApplied += zakatPaidInput;\n\n      let finalTaxPayable = computedTax - rebatesApplied;\n      if (finalTaxPayable < 0) finalTaxPayable = 0;\n\n      // Handle difference with pre-paid MTD/PCB\n      const mtdPaid = parseFloat(document.getElementById('tax-mtd-paid').value) || 0;\n      const taxDifference = mtdPaid - finalTaxPayable;\n\n      // Update Tax assessment outputs\n      document.getElementById('header-tax-sum').innerText = 'RM ' + finalTaxPayable.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('lbl-tax-payable').innerText = 'RM ' + finalTaxPayable.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('tax-final-liability-val').innerText = 'RM ' + finalTaxPayable.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      \n      document.getElementById('res-tax-chargeable').innerText = 'RM ' + chargeableIncome.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('res-tax-reliefs').innerText = 'RM ' + totalReliefs.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('res-tax-calculated-owed').innerText = 'RM ' + computedTax.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('res-tax-rebates').innerText = 'RM ' + rebatesApplied.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\n      // Live sidebar bindings\n      document.getElementById('sb-chargeable').innerText = 'RM ' + chargeableIncome.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('sb-tax-due').innerText = 'RM ' + finalTaxPayable.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\n      // Action description\n      const statusElement = document.getElementById('res-tax-status-text');\n      if (taxDifference > 0) {\n        statusElement.className = \"positive\";\n        statusElement.innerText = `Eligible Refund of RM ${taxDifference.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} (Overpaid MTD)`;\n      } else if (taxDifference < 0) {\n        statusElement.className = \"warning\";\n        statusElement.innerText = `Outstanding Balance of RM ${Math.abs(taxDifference).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} (To pay during e-filing)`;\n      } else {\n        statusElement.className = \"neutral\";\n        statusElement.innerText = \"Exactly balanced. No refund or tax outstanding.\";\n      }\n\n      return finalTaxPayable;\n    }\n\n    // Specific Zakat formula algorithm (replicates Selangor model)\n    function calculateZakat() {\n      const savingsVal = parseFloat(document.getElementById('zakat-savings-bal').value) || 0;\n      const stocksVal = parseFloat(document.getElementById('zakat-stocks-bal').value) || 0;\n      const storedGoldGrams = parseFloat(document.getElementById('zakat-gold-stored').value) || 0;\n      const wornGoldGrams = parseFloat(document.getElementById('zakat-gold-worn').value) || 0;\n      const goldPrice = parseFloat(document.getElementById('zakat-gold-price').value) || 0;\n\n      // 1. Analyze Stored Gold (Threshold Nisab is 85g)\n      let storedGoldAssessableVal = 0;\n      if (storedGoldGrams >= 85) {\n        storedGoldAssessableVal = storedGoldGrams * goldPrice;\n      }\n      document.getElementById('res-gold-stored-val').innerText = 'RM ' + storedGoldAssessableVal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\n      // 2. Analyze Worn Gold Ornaments (Exemption limit Uruf is 800g for Selangor)\n      let wornGoldAssessableVal = 0;\n      if (wornGoldGrams > 800) {\n        const excessGrams = wornGoldGrams - 800;\n        wornGoldAssessableVal = excessGrams * goldPrice;\n      }\n      document.getElementById('res-gold-worn-val').innerText = 'RM ' + wornGoldAssessableVal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\n      // Calculate overall assessable assets\n      const totalAssessableWealth = savingsVal + stocksVal + storedGoldAssessableVal + wornGoldAssessableVal;\n\n      let finalZakatDue = 0;\n      const nisabCheckElement = document.getElementById('res-zakat-nisab-check');\n\n      // Check against Selangor Nisab Threshold\n      if (totalAssessableWealth >= NISAB_THRESHOLD) {\n        finalZakatDue = totalAssessableWealth * 0.025;\n        nisabCheckElement.innerText = \"Exceeded (Subject to Zakat)\";\n        nisabCheckElement.className = \"res-sub-val warning\";\n      } else {\n        finalZakatDue = 0;\n        nisabCheckElement.innerText = \"Below Nisab (No Zakat Due)\";\n        nisabCheckElement.className = \"res-sub-val positive\";\n      }\n\n      // Update Zakat assessment outputs\n      document.getElementById('header-zakat-sum').innerText = 'RM ' + finalZakatDue.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('lbl-zakat-payable').innerText = 'RM ' + finalZakatDue.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('zakat-final-val').innerText = 'RM ' + finalZakatDue.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('res-zakat-wealth').innerText = 'RM ' + totalAssessableWealth.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\n      // Live sidebar bindings\n      document.getElementById('sb-zakat-wealth').innerText = 'RM ' + totalAssessableWealth.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n      document.getElementById('sb-zakat-due').innerText = 'RM ' + finalZakatDue.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\n      return finalZakatDue;\n    }\n\n    // Handles character counts and mirror print commentary text\n    function updateCommentary(type) {\n      const textarea = document.getElementById('commentary-' + type);\n      const counter = document.getElementById('char-count-' + type);\n      const printBox = document.getElementById('print-' + type + '-commentary');\n\n      counter.innerText = `${textarea.value.length} / 250 chars`;\n      \n      if (textarea.value.trim() === \"\") {\n        printBox.innerText = \"No notes specified.\";\n      } else {\n        printBox.innerText = textarea.value;\n      }\n    }\n\n    // Fully resets all configurations back to the standardized defaults\n    function resetAll() {\n      // Inputs\n      document.getElementById('tax-gross-income').value = 78000;\n      document.getElementById('tax-relief-medical').value = 1500;\n      document.getElementById('tax-relief-lifestyle').value = 2000;\n      document.getElementById('tax-relief-epf').value = 4000;\n      document.getElementById('tax-relief-life-ins').value = 3000;\n      document.getElementById('tax-relief-sspn').value = 0;\n      document.getElementById('tax-mtd-paid').value = 1800;\n      document.getElementById('tax-zakat-paid').value = 0;\n\n      document.getElementById('zakat-savings-bal').value = 18000;\n      document.getElementById('zakat-stocks-bal').value = 25000;\n      document.getElementById('zakat-gold-stored').value = 90;\n      document.getElementById('zakat-gold-worn').value = 15;\n      document.getElementById('zakat-gold-price').value = 340;\n\n      // Textareas\n      document.getElementById('commentary-tax').value = \"\";\n      document.getElementById('commentary-zakat').value = \"\";\n      updateCommentary('tax');\n      updateCommentary('zakat');\n\n      // Toggles\n      document.getElementById('chk-tax').checked = true;\n      document.getElementById('chk-zakat').checked = true;\n\n      handleCheckboxChange();\n    }\n  </script>\n</body>\n</html>";

window.WQPlanningSuiteModules = window.WQPlanningSuiteModules || [];
window.WQPlanningSuiteModules.push({
  id: "zakat-tax",
  title: "Zakat & Tax Planning",
  render(container) {
    container.innerHTML = '';
    const frame = document.createElement('iframe');
    frame.className = 'planning-suite-frame';
    frame.title = "Zakat & Tax Planning";
    frame.srcdoc = window.WQStorage?.injectScopedStorageIntoHtml?.(html, this.id) || html;
    const resizeFrame = () => {
      try {
        const doc = frame.contentDocument || frame.contentWindow?.document;
        if (!doc) return;
        const h = Math.max(760, doc.documentElement.scrollHeight, doc.body?.scrollHeight || 0);
        frame.style.height = `${h + 32}px`;
      } catch (_) {}
    };
    frame.addEventListener('load', () => {
      resizeFrame();
      let runs = 0;
      const timer = setInterval(() => {
        resizeFrame();
        runs += 1;
        if (runs > 12) clearInterval(timer);
      }, 500);
    });
    container.appendChild(frame);
  }
});

})();
